#include <format>
#include <string>
#include <string_view>

std::string row(std::string_view name, double price)
{
    return std::format("{:<12}{:>8.2f}", name, price);
}

std::string centred(std::string_view text, int width)
{
    return std::format("{:-^{}}", text, width);
}
